theorem measureReal_superlevel_mono [IsFiniteMeasure μ]
    {A B G : Ω → ℝ} (hAB : ∀ ω, A ω ≤ B ω) :
    μ.real {ω | B ω ≤ G ω} ≤ μ.real {ω | A ω ≤ G ω}

theorem pi_map_eval {ι: Type*} {Ω : ι → Type*} [Fintype ι] [DecidableEq ι]
  [∀ i, MeasurableSpace (Ω i)] {μ : (i : ι) → Measure (Ω i)}
  [∀ i, IsProbabilityMeasure (μ i)] (k : ι): (Measure.pi μ).map (Function.eval k) = (μ k)

lemma HasOrliczPsi1Bound.mono {X : Ω → ℝ} {μ : Measure Ω} {K K' : ℝ}
    (h : HasOrliczPsi1Bound X μ K) (hKK' : K ≤ K') :
    HasOrliczPsi1Bound X μ K'

lemma HasOrliczPsi2Bound.mono {X : Ω → ℝ} {μ : Measure Ω} {K K' : ℝ}
    (h : HasOrliczPsi2Bound X μ K) (hKK' : K ≤ K') :
    HasOrliczPsi2Bound X μ K'

lemma orliczPsi1Norm_sq_le {μ : Measure Ω} [IsProbabilityMeasure μ] {X : Ω → ℝ}
    (hXm : AEMeasurable X μ) (hXfin : HasFiniteOrliczPsi2Norm X μ) :
    orliczPsi1Norm (fun ω => X ω ^ 2) μ ≤ orliczPsi2Norm X μ ^ 2
